#include <windows.h>
#include <tlhelp32.h>
#include <atomic>
#include <cstdint>
#include <cstring>
#include <iostream>
#include <limits>
#include <string>
#include <thread>
#include <vector>

static DWORD findPid(const std::wstring& name) {
    DWORD pid = 0;
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (snap == INVALID_HANDLE_VALUE) return 0;
    PROCESSENTRY32W pe{};
    pe.dwSize = sizeof(pe);
    if (Process32FirstW(snap, &pe)) {
        do {
            if (_wcsicmp(pe.szExeFile, name.c_str()) == 0) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

static bool writable(const MEMORY_BASIC_INFORMATION& m) {
    if (m.State != MEM_COMMIT) return false;
    if (m.Protect & (PAGE_GUARD | PAGE_NOACCESS)) return false;
    return (m.Protect & (PAGE_READWRITE | PAGE_WRITECOPY | PAGE_EXECUTE_READWRITE | PAGE_EXECUTE_WRITECOPY)) != 0;
}

static std::vector<uintptr_t> firstScan(HANDLE h, int32_t value) {
    std::vector<uintptr_t> hits;
    SYSTEM_INFO si;
    GetSystemInfo(&si);
    auto addr = reinterpret_cast<uintptr_t>(si.lpMinimumApplicationAddress);
    auto end = reinterpret_cast<uintptr_t>(si.lpMaximumApplicationAddress);
    std::vector<uint8_t> buf;
    MEMORY_BASIC_INFORMATION m;
    while (addr < end && VirtualQueryEx(h, reinterpret_cast<LPCVOID>(addr), &m, sizeof(m)) == sizeof(m)) {
        auto base = reinterpret_cast<uintptr_t>(m.BaseAddress);
        if (writable(m)) {
            buf.resize(m.RegionSize);
            SIZE_T got = 0;
            if (ReadProcessMemory(h, m.BaseAddress, buf.data(), m.RegionSize, &got) || got > 0) {
                for (SIZE_T i = 0; i + sizeof(int32_t) <= got; i += sizeof(int32_t)) {
                    int32_t v;
                    std::memcpy(&v, buf.data() + i, sizeof(v));
                    if (v == value) hits.push_back(base + i);
                }
            }
        }
        addr = base + m.RegionSize;
    }
    return hits;
}

static std::vector<uintptr_t> nextScan(HANDLE h, const std::vector<uintptr_t>& in, int32_t value) {
    std::vector<uintptr_t> out;
    for (auto a : in) {
        int32_t v = 0;
        SIZE_T got = 0;
        if (ReadProcessMemory(h, reinterpret_cast<LPCVOID>(a), &v, sizeof(v), &got) && got == sizeof(v) && v == value)
            out.push_back(a);
    }
    return out;
}

static long long ask(const char* prompt) {
    long long v;
    std::cout << prompt;
    while (!(std::cin >> v)) {
        std::cin.clear();
        std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
        std::cout << prompt;
    }
    return v;
}

int main(int argc, char** argv) {
    if (argc < 2) { std::cerr << "usage: trainer.exe <process.exe>\n"; return 1; }
    std::string arg = argv[1];
    DWORD pid = findPid(std::wstring(arg.begin(), arg.end()));
    if (!pid) { std::cerr << "process not found\n"; return 1; }
    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { std::cerr << "OpenProcess failed: " << GetLastError() << "\n"; return 1; }

    auto hits = firstScan(h, static_cast<int32_t>(ask("current value: ")));
    std::cout << hits.size() << " hits\n";
    for (int pass = 1; pass <= 2 && !hits.empty(); ++pass) {
        auto v = static_cast<int32_t>(ask("change it in game, then enter new value: "));
        hits = nextScan(h, hits, v);
        std::cout << "pass " << pass << ": " << hits.size() << " hits\n";
    }
    if (hits.empty()) { std::cerr << "no hits left\n"; CloseHandle(h); return 1; }

    size_t shown = hits.size() < 20 ? hits.size() : 20;
    for (size_t i = 0; i < shown; ++i)
        std::cout << "[" << i << "] 0x" << std::hex << hits[i] << std::dec << "\n";
    auto idx = ask("index to freeze: ");
    if (idx < 0 || static_cast<size_t>(idx) >= shown) { std::cerr << "bad index\n"; CloseHandle(h); return 1; }
    uintptr_t target = hits[static_cast<size_t>(idx)];
    int32_t frozen = static_cast<int32_t>(ask("value to freeze at: "));

    std::atomic<bool> run{true};
    std::thread t([&] {
        while (run) {
            WriteProcessMemory(h, reinterpret_cast<LPVOID>(target), &frozen, sizeof(frozen), nullptr);
            Sleep(50);
        }
    });
    std::cout << "frozen at 0x" << std::hex << target << std::dec << ". press enter to stop.\n";
    std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
    std::cin.get();
    run = false;
    t.join();
    CloseHandle(h);
    return 0;
}
